      "content": "{\n  \"name\": \"dsh-thoughtdag\",\n  \"version\": \"0.5.27\",\n  \"description\": \"ThoughtDAG for DeepSeek Harness: turn the current DSH session into an editable thought graph on an infinite canvas. Source, releases and issues: github.com/chenxiachan/thoughtdag\",\n  \"author\": \"Xia Chen\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/chenxiachan/thoughtdag.git\",\n    \"directory\": \"dsh\"\n  },\n  \"homepage\": \"https://github.com/chenxiachan/thoughtdag/tree/main/dsh#readme\",\n  \"bugs\": \"https://github.com/chenxiachan/thoughtdag/issues\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"dist-app\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs ..\",\n    \"prepack\": \"npm run build\",\n    \"verify\": \"node scripts/verify-write-bridge.mjs\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-modules\",\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-workspace\"\n      ],\n      \"immediately\": false\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.5-rc.2\": \"compatible\",\n        \"0.1.5-rc.3\": \"compatible\"\n      }\n    }\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"thoughtdag\",\n    \"context\",\n    \"canvas\"\n  ],\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-session\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-api-session-controller\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-agent\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-attachment\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-web\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-client-modules\": \">=0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.2-rc.1\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-session\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-session-controller\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-agent\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-llm\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-attachment\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-web\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-modules\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    }\n  }\n}\n"
